/* From Uiverse.io by Mhyar-nsi - Tags: card, code, syntax, code block */
.__UIV_SCOPE__ .card {
  font-family: monospace;
  margin-top: 40px;
  width: 350px;
  height: 260px;
  background: #292828da;
  border: 2px solid #000;
  border-radius: 15px;
}

.__UIV_SCOPE__ .top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 10px;
}

.__UIV_SCOPE__ .dots {
  display: flex;
  justify-content: last baseline;
}

.__UIV_SCOPE__ .dot {
  width: 15px;
  height: 15px;
  border-radius: 50%;
}

.__UIV_SCOPE__ .dot-1 {
  background-color: rgb(0, 132, 255);
}

.__UIV_SCOPE__ .dot-2 {
  background-color: rgb(230, 0, 255);
}

.__UIV_SCOPE__ .dot-3 {
  background-color: rgb(0, 255, 89);
}

.__UIV_SCOPE__ .top p {
  font-size: 20px;
  font-weight: bold;
}

.__UIV_SCOPE__ .dot, .__UIV_SCOPE__ .top p {
  margin: 5px;
}

.__UIV_SCOPE__ .g-color {
  color: darkgreen;
}

.__UIV_SCOPE__ .bottom {
  margin-top: 30px;
  padding: 0 25px;
}

.__UIV_SCOPE__ .code {
  font-size: 15px;
}

.__UIV_SCOPE__ .red {
  color: rgb(210, 63, 52);
}

.__UIV_SCOPE__ .violet {
  color: rgb(181, 40, 203);
}

.__UIV_SCOPE__ .blue {
  color: rgb(91, 131, 223);
}

.__UIV_SCOPE__ .orange {
  color: rgb(195, 128, 3);
}

.__UIV_SCOPE__ .white {
  color: rgb(163, 163, 163);
}

.__UIV_SCOPE__ .space-4 {
  margin-left: 35px;
}

.__UIV_SCOPE__ .space-4x2 {
  margin-left: 70px;
}
